kinds.exampleCs:
// client
var trees = Vegetation.Kinds().Where(path => path.Contains("/trees/")).ToArray();
Log.Info(trees.Length);

plant.example:
// client
const { Vector3 } = kcds.math;

const fir = kcds.world.Vegetation.plant('abies_alba_forest_b', new Vector3(120, 200, 14), { scale: 1.2, turn: 30 });
if (fir) {
  fir.remove();
}

plant.exampleCs:
// client

var fir = Vegetation.Plant("abies_alba_forest_b", new Vector3(120, 200, 14), new { scale = 1.2, turn = 30 });
if (fir)
{
    fir.Call("remove");
}

plantMany.example:
// client
const { Vector3 } = kcds.math;

const row = [];
for (let step = 0; step < 20; step += 1) {
  row.push({ kind: 'abies_alba_forest_b', position: new Vector3(120 + step * 4, 200, 14), turn: step * 18 });
}
const planted = kcds.world.Vegetation.plantMany(row).filter(Boolean);
console.info(`${planted.length} firs planted`);

plantMany.exampleCs:
// client
var row = new List<object>();
for (var step = 0; step < 20; step += 1)
{
    row.Add(new { kind = "abies_alba_forest_b", position = new Vector3(120 + step * 4, 200, 14), turn = step * 18 });
}
var planted = Vegetation.PlantMany(row).Count((tree) => tree.AsBool());
Log.Info($"{planted} firs planted");

planted.example:
// client
for (const plant of kcds.world.Vegetation.planted()) {
  plant.remove();
}

planted.exampleCs:
// client
foreach (var plant in Vegetation.Planted())
{
    plant.Call("remove");
}
